CREATE COLUMN TABLE "TEST_AP"."OFRM" ("AbsEntry" INTEGER CS_INT NOT NULL , "Name" NVARCHAR(100), "Encoding" NVARCHAR(100), "FilePath" NCLOB MEMORY THRESHOLD 1000, "IsSystem" NVARCHAR(1) DEFAULT 'N', "FrmatType" NVARCHAR(1) DEFAULT 'O', "FileContnt" BLOB MEMORY THRESHOLD 1000, "FrmatStats" NVARCHAR(1) DEFAULT 'U', "PaymType" NVARCHAR(1) DEFAULT 'X', PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
ALTER TABLE "TEST_AP"."OFRM" WITH PARAMETERS ('CONCAT_ATTRIBUTE'=('$Name$FrmatType$','Name','FrmatType'));
CREATE INDEX "OFRM_NAME_TYPE" ON "TEST_AP"."OFRM" ( "Name" ASC, "FrmatType" ASC )